def test_init_db_creates_table(tmp_db):
    with tmp_db.get_conn() as conn:
        tables = conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name='cotizaciones'"
        ).fetchall()
    assert len(tables) == 1


def test_init_db_idempotent(tmp_db):
    """Calling init_db twice should not raise."""
    tmp_db.init_db()

def test_obtener_cotizaciones_empty_db(tmp_db):
    assert tmp_db.obtener_cotizaciones() == []


def test_obtener_cotizaciones_respects_limit(tmp_db):
    for i in range(5):
        tmp_db.guardar_cotizacion(f"Cliente{i}", "60000000", SAMPLE_ITEMS, 45.0, 0, 0.0, 45.0)
    rows = tmp_db.obtener_cotizaciones(limit=3)
    assert len(rows) == 3


def test_obtener_cotizaciones_newest_first(tmp_db):
    tmp_db.guardar_cotizacion("Primero", "60000001", SAMPLE_ITEMS, 45.0, 0, 0.0, 45.0)
    tmp_db.guardar_cotizacion("Segundo", "60000002", SAMPLE_ITEMS, 45.0, 0, 0.0, 45.0)
    rows = tmp_db.obtener_cotizaciones()
    assert rows[0]["cliente"] == "Segundo"

