"""
Tests for quotation business logic.
These tests document expected behavior; extract the logic into
a pure-function module (e.g. logic.py) to make them pass.
"""
from urllib.parse import quote, unquote
import pytest


def calcular_subtotal(items):
    return round(sum(x["subtotal"] for x in items), 2)


def calcular_descuento(subtotal, pct):
    return round(subtotal * pct / 100, 2)


def calcular_total(subtotal, descuento_monto):
    return round(subtotal - descuento_monto, 2)


def construir_mensaje(nombre, items, subtotal, descuento_pct, descuento_monto, total):
    lineas = "\n".join(
        f"• {it['servicio']} ×{it['cantidad']} = ${it['subtotal']:.2f}"
        for it in items
    )
    cuerpo = (
        f"Hola {nombre}, aquí tu cotización de MAGNEX INTERNATIONAL:\n\n"
        f"{lineas}\n\n"
        + (f"Subtotal: ${subtotal:.2f}\nDescuento ({descuento_pct}%): -${descuento_monto:.2f}\n"
           if descuento_pct else "")
        + f"*TOTAL: ${total:.2f}*\n\n¡Gracias por preferirnos! ⚡"
    )
    return cuerpo


def construir_link_wa(whatsapp, cuerpo):
    return f"https://wa.me/507{whatsapp}?text={quote(cuerpo)}"

def test_subtotal_single_item():
    items = [{"servicio": "X", "cantidad": 2, "precio_unit": 45.0, "subtotal": 90.0}]
    assert calcular_subtotal(items) == 90.0


def test_subtotal_multiple_items():
    items = [
        {"servicio": "A", "cantidad": 1, "precio_unit": 25.0, "subtotal": 25.0},
        {"servicio": "B", "cantidad": 3, "precio_unit": 10.0, "subtotal": 30.0},
    ]
    assert calcular_subtotal(items) == 55.0


def test_subtotal_empty_cart():
    assert calcular_subtotal([]) == 0.0


def test_subtotal_zero_price_item():
    """Pulimiento de Pisos has precio_base = 0."""
    items = [{"servicio": "Pulimiento de Pisos", "cantidad": 1, "precio_unit": 0.0, "subtotal": 0.0}]
    assert calcular_subtotal(items) == 0.0

def test_descuento_zero_pct():
    assert calcular_descuento(100.0, 0) == 0.0


def test_descuento_10_pct():
    assert calcular_descuento(100.0, 10) == 10.0


def test_descuento_100_pct():
    assert calcular_descuento(100.0, 100) == 100.0


def test_descuento_rounds_to_two_decimals():
    assert calcular_descuento(33.33, 10) == pytest.approx(3.33, abs=0.01)

def test_total_no_discount():
    assert calcular_total(100.0, 0.0) == 100.0


def test_total_with_discount():
    assert calcular_total(100.0, 10.0) == 90.0


def test_total_full_discount_is_zero():
    assert calcular_total(100.0, 100.0) == 0.0

