ITEMS = [{"servicio": "Colchón Queen", "cantidad": 1, "precio_unit": 45.0, "subtotal": 45.0}]


def test_mensaje_contains_client_name():
    msg = construir_mensaje("Ana", ITEMS, 45.0, 0, 0.0, 45.0)
    assert "Ana" in msg


